const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  Header, Footer, AlignmentType, PageOrientation, LevelFormat,
  TabStopType, TabStopPosition, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageNumber, PageBreak
} = require('docx');

// Brand colors
const NAVY = "0A2342";
const GOLD = "B8860B";
const LIGHT_GOLD = "F5EFDB";
const SOFT_GREY = "EFEFEF";
const DARK_TEXT = "1A1A1A";

// Helpers
const border = { style: BorderStyle.SINGLE, size: 4, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };

const goldRule = new Paragraph({
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 4 } },
  spacing: { before: 60, after: 240 },
  children: [new TextRun({ text: "" })]
});

const spacer = (size = 120) => new Paragraph({ spacing: { before: 0, after: size }, children: [new TextRun({ text: "" })] });

const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 120 },
  children: [new TextRun({ text, bold: true, color: NAVY, size: 32, font: "Calibri" })]
});

const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 280, after: 100 },
  children: [new TextRun({ text, bold: true, color: NAVY, size: 26, font: "Calibri" })]
});

const h3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  spacing: { before: 220, after: 80 },
  children: [new TextRun({ text, bold: true, color: GOLD, size: 22, font: "Calibri", allCaps: true })]
});

const body = (text, opts = {}) => new Paragraph({
  spacing: { before: 60, after: 120, line: 300 },
  alignment: AlignmentType.LEFT,
  children: [new TextRun({ text, color: DARK_TEXT, size: 22, font: "Calibri", ...opts })]
});

const bodyMixed = (runs) => new Paragraph({
  spacing: { before: 60, after: 120, line: 300 },
  alignment: AlignmentType.LEFT,
  children: runs.map(r => new TextRun({ color: DARK_TEXT, size: 22, font: "Calibri", ...r }))
});

const bullet = (text, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { before: 40, after: 40, line: 290 },
  children: [new TextRun({ text, color: DARK_TEXT, size: 22, font: "Calibri" })]
});

const bulletMixed = (runs, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { before: 40, after: 40, line: 290 },
  children: runs.map(r => new TextRun({ color: DARK_TEXT, size: 22, font: "Calibri", ...r }))
});

const numbered = (text) => new Paragraph({
  numbering: { reference: "numbers", level: 0 },
  spacing: { before: 60, after: 60, line: 290 },
  children: [new TextRun({ text, color: DARK_TEXT, size: 22, font: "Calibri" })]
});

// Callout box
const callout = (titleText, bodyParagraphs) => new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [9360],
  rows: [
    new TableRow({
      children: [
        new TableCell({
          borders: {
            top: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            left: { style: BorderStyle.SINGLE, size: 24, color: GOLD },
            right: { style: BorderStyle.SINGLE, size: 4, color: GOLD }
          },
          width: { size: 9360, type: WidthType.DXA },
          shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
          margins: { top: 200, bottom: 200, left: 240, right: 240 },
          children: [
            new Paragraph({
              spacing: { before: 0, after: 100 },
              children: [new TextRun({ text: titleText, bold: true, color: NAVY, size: 22, font: "Calibri", allCaps: true })]
            }),
            ...bodyParagraphs
          ]
        })
      ]
    })
  ]
});

// Two-column table for partner details
const partnerTable = (rows) => new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [2700, 6660],
  rows: rows.map(([label, value], i) => new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 2700, type: WidthType.DXA },
        shading: { fill: NAVY, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({
          children: [new TextRun({ text: label, bold: true, color: "FFFFFF", size: 20, font: "Calibri", allCaps: true })]
        })]
      }),
      new TableCell({
        borders,
        width: { size: 6660, type: WidthType.DXA },
        shading: { fill: i % 2 === 0 ? "FFFFFF" : SOFT_GREY, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 140 },
        children: [new Paragraph({
          children: [new TextRun({ text: value, color: DARK_TEXT, size: 20, font: "Calibri" })]
        })]
      })
    ]
  }))
});

// ============ COVER PAGE ============
const coverPage = [
  new Paragraph({ spacing: { before: 1800 }, children: [new TextRun({ text: "" })] }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 120 },
    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, color: GOLD, size: 24, font: "Calibri", allCaps: true, characterSpacing: 60 })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 8 } },
    spacing: { before: 0, after: 240 },
    children: [new TextRun({ text: "PLAYBOOK SERIES", color: NAVY, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  new Paragraph({ spacing: { before: 480 }, children: [new TextRun({ text: "" })] }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 80 },
    children: [new TextRun({ text: "The Longevity Playbook", bold: true, color: NAVY, size: 56, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 360 },
    children: [new TextRun({ text: "Adding Peptide Health and Wellness to Your Med Spa", italics: true, color: NAVY, size: 28, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 80 },
    children: [new TextRun({ text: "How independent med spas turn aesthetics into longevity,", color: DARK_TEXT, size: 22, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 1200 },
    children: [new TextRun({ text: "double client lifetime value, and own the next decade of beauty.", color: DARK_TEXT, size: 22, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    border: { top: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 8 } },
    spacing: { before: 240, after: 80 },
    children: [new TextRun({ text: "Bethany Anne", bold: true, color: NAVY, size: 22, font: "Calibri" })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "Co-Founder & CEO, The Luxora Collective", color: DARK_TEXT, size: 20, font: "Calibri", italics: true })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    spacing: { before: 60, after: 0 },
    children: [new TextRun({ text: "theluxoracollective.co", color: GOLD, size: 20, font: "Calibri" })]
  }),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ TABLE OF CONTENTS ============
const tocPage = [
  h1("Table of Contents"),
  goldRule,
  ...[
    ["01", "The Longevity Shift in Aesthetics", "4"],
    ["02", "Why Peptides, and Why Now", "6"],
    ["03", "The Core Peptide Menu for Med Spas", "8"],
    ["04", "Embedding Peptides Into Memberships", "12"],
    ["05", "Embedding Peptides Into Packages", "15"],
    ["06", "Embedding Peptides Into Consultations", "18"],
    ["07", "Compliance, Liability, and Sourcing", "21"],
    ["08", "Suggested Partners to Fill the Gap", "23"],
    ["09", "Implementation Roadmap, First 90 Days", "27"],
    ["10", "Closing, The Owner Standard", "30"]
  ].map(([num, title, page]) => new Paragraph({
    tabStops: [{ type: TabStopType.RIGHT, position: 9000, leader: "dot" }],
    spacing: { before: 100, after: 100 },
    children: [
      new TextRun({ text: num, bold: true, color: GOLD, size: 22, font: "Calibri" }),
      new TextRun({ text: "    " + title, color: NAVY, size: 22, font: "Calibri" }),
      new TextRun({ text: "\t" + page, color: DARK_TEXT, size: 22, font: "Calibri" })
    ]
  })),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 01 ============
const section01 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 01", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  h1("The Longevity Shift in Aesthetics"),
  goldRule,
  body("Aesthetics is no longer a category by itself. The client who walks into a med spa today is not asking for a single result, she is asking for a longer, healthier, better-looking decade. She is reading about hormone optimization, GLP-1s, NAD+, peptide therapy, sleep architecture, and biological age testing. She is the same client who used to book one filler appointment a year. Now she wants a partner."),
  body("The independent med spa that still sells transactions is going to lose her. Not to the chain on the corner, to the longevity clinic two miles away that opened last year and figured out how to bundle peptides, IV therapy, and aesthetics under one roof."),
  body("This playbook exists for one reason. To give Luxora clients the framework, the language, and the partner network to add peptide-led longevity to every membership, every package, and every consultation, without losing brand, margin, or compliance footing."),
  h2("What changed"),
  body("Three things changed at the same time, and the owners who see it are pulling away from the rest."),
  numbered("The client redefined what beauty means. She wants to look 35 at 50 because she wants to live well at 80. Aesthetics is now downstream of health."),
  numbered("Peptide therapy moved from biohacker forums to mainstream wellness. Clients are asking for it by name. If the front desk cannot answer the question, the client googles it on the way home and books somewhere else."),
  numbered("The economics flipped. A client on a quarterly aesthetic cadence spends a known number per year. The same client on aesthetic plus peptide protocols spends two to four times that, and stays two to three times longer."),
  callout("THE LUXORA POSITION", [
    body("We do not believe peptides replace aesthetics. We believe peptides are the floor that makes aesthetics work. Skin, hair, body composition, and recovery all improve when the system underneath improves. The owner who sells peptides as a complement to her existing menu builds a business that compounds. The owner who ignores them is competing on price by the end of next year.", { color: NAVY })
  ]),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 02 ============
const section02 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 02", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  h1("Why Peptides, and Why Now"),
  goldRule,
  body("Peptides are short chains of amino acids that signal the body to do specific things, repair tissue, modulate inflammation, regulate appetite, support hormone production, improve sleep depth, accelerate skin and hair regeneration. They are not steroids, they are not hormones, they are signaling molecules. Used correctly, under provider oversight, they sit cleanly inside the wellness category that med spa clients already trust the owner to deliver."),
  h2("The four reasons this belongs in your med spa"),
  h3("Reason one, the client is already buying it"),
  body("She is buying it from a longevity clinic, a telehealth peptide subscription, a compounding pharmacy with a sales rep, or a friend with a connection. Every one of those dollars is a dollar she is not spending with you. Peptide therapy lives in the same emotional category as aesthetics, she trusts you for the outside, the question is whether you have earned the inside."),
  h3("Reason two, peptides amplify everything else on your menu"),
  body("BPC-157 supports recovery from microneedling, RF, and laser. GHK-Cu drives skin remodeling alongside topicals and energy-based devices. Tesamorelin and ipamorelin shift body composition, which makes body contouring stick. Semaglutide and tirzepatide protocols change the entire trajectory of a body client. The protocols are not parallel to aesthetics, they multiply aesthetics."),
  h3("Reason three, the lifetime value math is undeniable"),
  body("A typical aesthetic-only member spends between 3,600 and 7,200 dollars per year. A member on a properly built peptide and aesthetic protocol spends between 9,000 and 18,000 dollars per year, and her retention curve flattens because she is on a monthly clinical cadence, not a quarterly one. The owner does not need more leads, she needs to charge the right number for the right outcome to the clients she already has."),
  h3("Reason four, it future-proofs the brand"),
  body("Five years from now, the independent med spa that did not add a longevity arm is going to look like the salon that did not add color. The category is moving, the only question is whether the owner moves with it or watches it pass."),
  callout("WHAT THIS PLAYBOOK ASSUMES", [
    body("This playbook assumes the owner is not herself a prescriber, is not running a primary care or hormone clinic, and does not have a medical director who will write peptide protocols on day one. That is the most common starting point. The Luxora model is to build the offer, then plug in a partner who handles the medical side, while the spa retains the client relationship and the recurring revenue.", { color: NAVY })
  ]),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 03 ============
const section03 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 03", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  h1("The Core Peptide Menu for Med Spas"),
  goldRule,
  body("Not every peptide belongs in a med spa. The list below is the working Luxora shortlist, the peptides that are the most defensible from a compliance, demand, and outcome standpoint, and that map cleanly to aesthetic and wellness positioning. The owner does not need to offer all of them. She needs to pick three to five and master the language around them."),
  body("Final protocol, dosing, and administration must come from a licensed prescriber. The descriptions below are educational, written to help the owner and front desk speak fluently to clients."),

  h2("Skin, hair, and recovery peptides"),

  h3("BPC-157"),
  body("Body Protection Compound. Known for tissue repair, gut lining support, and reduction of inflammation. The most-asked-about peptide in the post-procedure recovery conversation. Pairs naturally with microneedling, RF microneedling, laser resurfacing, and PRP."),

  h3("GHK-Cu, copper peptide"),
  body("Drives collagen and elastin production, supports hair follicle health, and accelerates skin remodeling. Available in topical and injectable forms. The cleanest cross-sell with any skin or hair menu the spa already runs."),

  h3("Thymosin Beta-4, TB-500"),
  body("Recovery, soft tissue repair, and anti-inflammatory action. Often paired with BPC-157 for clients recovering from procedures or training hard. A favorite of athletic and high-performing clients in the 35 to 60 range."),

  h3("Epitalon"),
  body("Studied for telomere support and circadian regulation. The story peptide for the longevity-curious client who is asking the bigger questions about aging at the cellular level."),

  h2("Body composition and metabolic peptides"),

  h3("Semaglutide and tirzepatide"),
  body("GLP-1 and dual GLP-1, GIP agonists. The category that pulled longevity into the mainstream. Properly programmed, they change body composition and the client's relationship with the spa, monthly visits, monthly check-ins, monthly revenue. Improperly programmed, they create muscle loss and rebound. This is where a real medical partner matters."),

  h3("Tesamorelin"),
  body("Growth hormone releasing hormone analog. Studied for visceral fat reduction and body composition shifts in adult populations. Higher trust tier, requires a prescriber who knows the protocol."),

  h3("CJC-1295 and ipamorelin"),
  body("Growth hormone secretagogues, often stacked. Support sleep depth, recovery, lean mass, and skin quality. The most common longevity stack for aesthetic clients in their 40s and 50s."),

  h3("AOD-9604"),
  body("Fragment of human growth hormone, studied for fat metabolism without growth-related side effects. Often positioned as an entry-tier body composition peptide."),

  h2("Sexual health, mood, and sleep peptides"),

  h3("PT-141, bremelanotide"),
  body("Sexual desire and arousal support, for both female and male clients. The most under-marketed revenue line in independent med spas, because owners are uncomfortable selling it. The clients who want it want it badly."),

  h3("Selank and Semax"),
  body("Nootropic, mood, and cognitive support peptides. Pair with the executive female client who is also booking aesthetic services and sleeping four hours a night."),

  h3("DSIP, delta sleep-inducing peptide"),
  body("Sleep architecture support. Fits the longevity narrative cleanly, sleep is the single highest-ROI lever in skin quality, body composition, and mood."),

  callout("THE LUXORA SHORTLIST", [
    body("If you are starting from zero, build the launch menu around four peptides. One skin peptide, GHK-Cu. One recovery peptide, BPC-157. One body composition peptide, semaglutide or tirzepatide via partner. One quality of life peptide, the CJC-1295 plus ipamorelin stack. That is enough to write memberships, packages, and consultation language around. You can always expand. You cannot recover from launching with a confused menu.", { color: NAVY })
  ]),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 04 ============
const section04 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 04", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  h1("Embedding Peptides Into Memberships"),
  goldRule,
  body("Memberships are the single highest-leverage place to install peptide therapy, because memberships are already where the spa has trained the client to expect monthly value. Adding a peptide arm does not create a new buying motion, it deepens the one the client is already in."),
  h2("The three-tier longevity membership architecture"),
  body("The Luxora-recommended structure is to keep the existing aesthetic membership as the base, then layer two longevity tiers above it. The point is not to force every member to upgrade, the point is to give the right member a clear path."),

  h3("Tier one, Glow Member"),
  body("Existing aesthetic membership. Facial cadence, peel cadence, treatment credit, product discount. No peptides included. Position this as the entry tier for the client who is not ready to commit to the longevity conversation."),

  h3("Tier two, Glow Plus Longevity"),
  body("Everything in tier one, plus a topical peptide protocol included in the monthly cost, GHK-Cu serum or compounded copper peptide topical, plus one quarterly recovery peptide protocol via the partner clinic, BPC-157 or TB-500 cycle. This is the most-converted tier, because it adds the longevity story without requiring the client to engage with injectables yet."),

  h3("Tier three, Longevity Signature"),
  body("Everything in tier two, plus a quarterly clinical consultation with the partner prescriber, ongoing peptide protocol coverage, lab review, and aesthetic credit at a higher dollar value. This is the tier that should be priced between 497 and 1,200 dollars per month depending on the market, and it is the tier that anchors the entire program. A small percentage of the spa's client base will buy this tier, and that small percentage will become 30 to 45 percent of the spa's recurring revenue inside twelve months."),

  h2("How the money flows"),
  body("In the partner model, the spa keeps the membership relationship and the membership dollar. The partner clinic handles the medical side, the prescription, the protocol, the pharmacy relationship, and is paid through one of three structures, a per-protocol fee, a revenue share, or a flat monthly clinical fee per active longevity member. The Luxora team builds the financial model with each client based on which structure protects margin and brand."),

  h2("Front desk language for the upsell"),
  body("This is the script the front desk uses when a current Glow Member asks about peptides, hormones, or longevity. Train every team member on it and audit it weekly."),
  callout("THE UPSELL LINE", [
    body("\"That is exactly the conversation we built our Longevity Signature membership around. We partnered with a clinical team specifically so our members could get peptide and hormone support without having to start over with a new provider. Would you like me to put fifteen minutes on the calendar with our coordinator so we can walk you through what your protocol could look like?\"", { color: NAVY, italics: true })
  ]),
  body("Notice what that line does. It does not pitch. It does not list peptides. It moves the client to a conversation where the protocol is built, the prescriber is met, and the membership is upgraded in a single appointment."),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 05 ============
const section05 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 05", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  h1("Embedding Peptides Into Packages"),
  goldRule,
  body("Packages are the second major install point. The package client is buying a defined transformation, weight, skin, hair, post-pregnancy recovery, perimenopause. Every one of those transformations is more durable when peptides are part of the protocol. The owner who sells skin packages without a peptide arm is leaving outcomes on the table, and outcomes are what create referrals."),

  h2("The five core packages, rebuilt for longevity"),

  h3("Package one, Skin Reset"),
  body("Existing structure, microneedling series, peels, LED, take-home actives. Longevity layer, GHK-Cu topical or compounded copper peptide serum included in the package, optional BPC-157 recovery protocol available as a partner-clinic add-on. Reframe the package outcome from skin texture to skin biology."),

  h3("Package two, Hair Restoration"),
  body("Existing structure, PRP or PRF series, exosome treatments, scalp protocols. Longevity layer, GHK-Cu scalp serum included, optional partner-clinic peptide protocol for systemic hair support. Reframe outcome from hair growth to hair health, which lets the package live longer in the client's life."),

  h3("Package three, Body Transformation"),
  body("Existing structure, body contouring, RF or laser fat reduction, lymphatic protocols. Longevity layer, partner-clinic GLP-1 program structured into the package timeline, with the spa coordinating the aesthetic portion and the partner handling medical oversight. This is the package that doubles in revenue when peptides are inside it, because the body contouring outcome holds."),

  h3("Package four, Hormone and Hair, the perimenopause package"),
  body("New package category, built specifically for the 38 to 58 demographic. Existing structure can pull from skin, hair, and body. Longevity layer, partner-clinic hormone evaluation and peptide protocol coverage, including ipamorelin or CJC-1295 stack and consideration of PT-141 or Selank where appropriate. This is the package the independent med spa should price highest and market hardest, because no one else in the local market is positioning to this client correctly."),

  h3("Package five, Post-Procedure Recovery"),
  body("Existing structure, the spa's surgical-recovery or post-injectable recovery service. Longevity layer, BPC-157 and TB-500 protocols via the partner clinic. Position this package to plastic surgeons and dermatologists in the area as a downstream referral channel. The recovery package becomes a partnership tool as much as a revenue tool."),

  h2("Pricing principle"),
  body("When peptides go inside a package, the package price moves up by 20 to 40 percent, depending on what is included. The owner who is afraid to raise the price is the owner who has not understood what the new offer actually delivers. Luxora clients are coached to use the package rebuild as the moment to reset their entire pricing posture, because the new offer is meaningfully different from the old one."),

  callout("THE PACKAGE NAMING RULE", [
    body("Do not put the word peptide in the package name. The package name carries the outcome, Skin Reset, Hair Restoration, Body Transformation, Perimenopause Reset, Recovery Reset. Peptides live in the package description, the consultation, and the deliverables. The reason is simple, the client is not buying a peptide, she is buying the result the peptide produces.", { color: NAVY })
  ]),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 06 ============
const section06 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 06", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
  h1("Embedding Peptides Into Consultations"),
  goldRule,
  body("If memberships and packages are where peptides get monetized, consultations are where they get earned. The consultation is the single most important conversation in the spa, and most independent med spas are still running it like a transaction. The Luxora consultation model is built to do three things at once, surface the aesthetic concern, surface the longevity concern, and present the program that handles both."),

  h2("The four-question longevity intake"),
  body("Add these four questions to every consultation intake form, regardless of whether the client booked an aesthetic service or a longevity service. The point of the questions is not to gatekeep, it is to open the door so the provider has language to use later."),
  numbered("Outside of how you look, what is the one thing about your health right now that you would change if you could? Sleep, energy, weight, recovery, mood, hormones, sex drive."),
  numbered("On a scale of one to ten, how would you rate your energy in the afternoon?"),
  numbered("Have you ever explored peptide therapy, hormone optimization, or a longevity-focused medical program?"),
  numbered("If we could pair your aesthetic plan with a wellness plan that supports your skin and your body from the inside, would you want to hear how that works?"),

  h2("The consultation flow, phase by phase"),

  h3("Phase one, the surface"),
  body("Front desk or coordinator runs the standard aesthetic intake. Client describes the visible concern, fine lines, jowls, body shape, skin texture, hair thinning. Provider listens, takes notes, does not pitch."),

  h3("Phase two, the under"),
  body("Provider transitions with one line. \"Before we plan the treatment, I want to understand a little bit about how you are feeling overall, because the result we get on the surface is always going to track with what is happening underneath.\" The provider then asks the four longevity intake questions, slowly, with eye contact."),

  h3("Phase three, the bridge"),
  body("Provider connects the dots out loud. \"Based on what you described, I think the best plan for you is going to combine our skin work with a peptide and recovery protocol. I have a clinical partner I trust who handles that side, and we coordinate the two halves so you are not managing two providers.\" The provider does not name peptides at this stage, the language stays at the protocol level."),

  h3("Phase four, the offer"),
  body("Coordinator presents the package or membership tier that maps to what the provider just described. The price is presented in monthly numbers when possible, and financing is offered through Klarna or Affirm where appropriate. The coordinator books the partner-clinic intake on the same calendar before the client leaves."),

  h2("The two consultation outcomes"),
  body("Every Luxora consultation should end in one of two places. Either the client leaves with a single integrated plan that includes aesthetic and longevity elements, or the client leaves with a clear, dated next step to evaluate the longevity arm separately. There is no third option, and there is no consultation that ends in \"think about it.\" The owner who tolerates the third option is the owner whose conversion rate is going to stay below 40 percent forever."),
  new Paragraph({ children: [new PageBreak()] })
];

// ============ SECTION 07 ============
const section07 = [
  new Paragraph({
    spacing: { before: 0, after: 0 },
    children: [new TextRun({ text: "SECTION 07", bold: true, color: GOLD, size: 18, font: "Calibri", characterSpacing: 80 })]
  }),
